from __future__ import annotations

from typing import Any, Callable

from .errors import ConflictError, NotFoundError, ValidationError
from .model import Agent, Closure, Map, Mission, identifier, parse_closures
from .solver import (
    Closures,
    DEFAULT_ORDER_BUDGET,
    DEFAULT_TREE_BUDGET,
    detect_conflicts,
    plan_mission,
    position_at,
)
from .store import Store

MAX_ORDER_BUDGET = 5040
MAX_TREE_BUDGET = 4096


class SwarmGrid:
    """MAPF scheduling service: maps in, missions in, conflict-free joint plans out."""

    def __init__(self, database: str):
        self.store = Store(database)
        self._maps: dict[str, Map] = {}

    # ------------------------------------------------------------------ #
    # maps
    # ------------------------------------------------------------------ #

    def create_map(self, raw: Any, key: str | None) -> dict[str, Any]:
        record = Map.parse(raw)

        def create() -> dict[str, Any]:
            existing = self.store.connection.execute(
                "SELECT 1 FROM maps WHERE id = ?", (record.id,)
            ).fetchone()
            if existing:
                raise ConflictError(f"map {record.id} already exists")
            self.store.connection.execute(
                "INSERT INTO maps(id, document) VALUES (?, ?)",
                (record.id, self.store.encode(record.as_dict())),
            )
            return record.as_dict()

        return self._idempotent(key, f"create-map:{record.id}", create)

    def get_map(self, map_id: str) -> dict[str, Any]:
        return self._load_map(map_id).as_dict()

    def _load_map(self, map_id: str) -> Map:
        cached = self._maps.get(map_id)
        if cached is not None:
            return cached
        row = self.store.connection.execute(
            "SELECT document FROM maps WHERE id = ?", (map_id,)
        ).fetchone()
        if not row:
            raise NotFoundError(f"map {map_id} was not found")
        record = Map.parse(self.store.decode(row["document"]))
        self._maps[map_id] = record
        return record

    # ------------------------------------------------------------------ #
    # missions
    # ------------------------------------------------------------------ #

    def create_mission(self, raw: Any, key: str | None) -> dict[str, Any]:
        if not isinstance(raw, dict):
            raise ValidationError("mission must be an object")
        unknown = sorted(set(raw) - {"id", "map_id", "agents"})
        if unknown:
            raise ValidationError(f"mission contains unknown fields: {', '.join(unknown)}")
        for field in ("id", "map_id", "agents"):
            if field not in raw:
                raise ValidationError(f"mission is missing required field: {field}")
        mission_id = identifier(raw["id"], "mission id")
        map_id = identifier(raw["map_id"], "map_id")
        map_record = self._load_map(map_id)
        mission = Mission.parse(raw, map_record)

        def create() -> dict[str, Any]:
            existing = self.store.connection.execute(
                "SELECT 1 FROM missions WHERE id = ?", (mission_id,)
            ).fetchone()
            if existing:
                raise ConflictError(f"mission {mission_id} already exists")
            state = {
                "id": mission_id,
                "map_id": map_id,
                "status": "created",
                "created_at": self.store.now(),
                "agents": [agent.as_dict() for agent in mission.agents],
            }
            self.store.connection.execute(
                "INSERT INTO missions(id, map_id, state, plan) VALUES (?, ?, ?, NULL)",
                (mission_id, map_id, self.store.encode(state)),
            )
            return state

        return self._idempotent(key, f"create-mission:{mission_id}", create)

    def get_mission(self, mission_id: str) -> dict[str, Any]:
        state, plan = self._load_mission(mission_id)
        view = dict(state)
        view["plan"] = plan
        return view

    def _load_mission(self, mission_id: str) -> tuple[dict[str, Any], dict[str, Any] | None]:
        row = self.store.connection.execute(
            "SELECT state, plan FROM missions WHERE id = ?", (mission_id,)
        ).fetchone()
        if not row:
            raise NotFoundError(f"mission {mission_id} was not found")
        state = self.store.decode(row["state"])
        plan = self.store.decode(row["plan"]) if row["plan"] is not None else None
        return state, plan

    def plan(self, mission_id: str, raw: Any, key: str | None) -> dict[str, Any]:
        """Plan `mission_id`, returning the stored plan when it was already solved."""

        def resolve() -> dict[str, Any]:
            state, stored_plan = self._load_mission(mission_id)
            if state["status"] == "solved" and stored_plan is not None:
                return stored_plan

            map_record = self._load_map(state["map_id"])
            mission = self._rebuild_mission(state)
            requested, order_budget, tree_budget, closures = self._plan_options(
                raw, mission, map_record
            )
            result = plan_mission(
                map_record, mission, requested, order_budget, tree_budget, closures
            )
            plan = self._materialize(mission, result)
            self._assert_plan_invariants(mission, plan, closures)

            if result.status == "solved":
                state["status"] = "solved"
                state["planned_at"] = self.store.now()
                self.store.connection.execute(
                    "UPDATE missions SET state = ?, plan = ? WHERE id = ?",
                    (self.store.encode(state), self.store.encode(plan), mission_id),
                )
            else:
                state["status"] = "unsolvable"
                state["planned_at"] = self.store.now()
                self.store.connection.execute(
                    "UPDATE missions SET state = ?, plan = NULL WHERE id = ?",
                    (self.store.encode(state), mission_id),
                )
            return plan

        return self._idempotent(key, f"plan-mission:{mission_id}", resolve)

    def schedule(self, mission_id: str) -> dict[str, Any]:
        """Timeline of the solved plan: one frame per timestep from 0 to makespan."""
        state, plan = self._load_mission(mission_id)
        if state["status"] != "solved" or plan is None:
            raise ConflictError(f"mission {mission_id} has no solved plan to schedule")
        paths = {
            entry["agent_id"]: [(int(cell[0]), int(cell[1])) for cell in entry["path"]]
            for entry in plan["agents"]
        }
        return {
            "mission_id": mission_id,
            "map_id": state["map_id"],
            "makespan": plan["makespan"],
            "priority_order": plan["priority_order"],
            "timeline": [
                {
                    "timestep": timestep,
                    "positions": {
                        agent_id: (
                            list(position) if (position := position_at(path, timestep)) else None
                        )
                        for agent_id, path in sorted(paths.items())
                    },
                }
                for timestep in range(plan["makespan"] + 1)
            ],
        }

    # ------------------------------------------------------------------ #
    # internals
    # ------------------------------------------------------------------ #

    def _plan_options(self, raw: Any, mission: Mission, map_record: Map) -> tuple[
        list[str] | None, int, int, Closures
    ]:
        if raw is None:
            return None, DEFAULT_ORDER_BUDGET, DEFAULT_TREE_BUDGET, ()
        if not isinstance(raw, dict):
            raise ValidationError("plan body must be an object")
        unknown = sorted(set(raw) - {"priority", "order_budget", "tree_budget", "closures"})
        if unknown:
            raise ValidationError(f"plan body contains unknown fields: {', '.join(unknown)}")
        known = sorted(agent.id for agent in mission.agents)
        priority = raw.get("priority")
        if priority is not None:
            if not isinstance(priority, list) or any(
                not isinstance(agent_id, str) or not agent_id for agent_id in priority
            ):
                raise ValidationError("priority must be an array of non-empty agent id strings")
            if len(set(priority)) != len(priority):
                raise ValidationError("priority must not repeat an agent id")
            if sorted(priority) != known:
                raise ValidationError("priority must list every agent of the mission exactly once")
        budget = raw.get("order_budget", DEFAULT_ORDER_BUDGET)
        if isinstance(budget, bool) or not isinstance(budget, int) or budget < 1 or budget > MAX_ORDER_BUDGET:
            raise ValidationError(f"order_budget must be an integer between 1 and {MAX_ORDER_BUDGET}")
        tree_budget = raw.get("tree_budget", DEFAULT_TREE_BUDGET)
        if (
            isinstance(tree_budget, bool)
            or not isinstance(tree_budget, int)
            or tree_budget < 0
            or tree_budget > MAX_TREE_BUDGET
        ):
            raise ValidationError(f"tree_budget must be an integer between 0 and {MAX_TREE_BUDGET}")
        closures = parse_closures(raw.get("closures"), map_record)
        return (
            list(priority) if priority is not None else None
        ), budget, tree_budget, closures

    def _rebuild_mission(self, state: dict[str, Any]) -> Mission:
        raw = {
            "id": state["id"],
            "map_id": state["map_id"],
            "agents": [
                {"id": entry["id"], "start": entry["start"], "goal": entry["goal"]}
                for entry in state["agents"]
            ],
        }
        return Mission.parse(raw, self._load_map(state["map_id"]))

    def _materialize(self, mission: Mission, result: Any) -> dict[str, Any]:
        by_id = {agent.id: agent for agent in mission.agents}
        if result.status == "solved":
            agents = [
                {
                    "agent_id": agent_id,
                    "start": list(by_id[agent_id].start),
                    "goal": list(by_id[agent_id].goal),
                    "arrival": len(path) - 1,
                    "path": [list(cell) for cell in path],
                }
                for agent_id, path in zip(result.order, result.paths)
            ]
            return {
                "mission_id": mission.id,
                "map_id": mission.map_id,
                "status": "solved",
                "method": result.method,
                "makespan": result.solution_makespan,
                "priority_order": list(result.order),
                "orders_tried": result.orders_tried,
                "orders_budget": result.orders_budget,
                "agents": sorted(agents, key=lambda entry: entry["agent_id"]),
            }
        return {
            "mission_id": mission.id,
            "map_id": mission.map_id,
            "status": "unsolvable",
            "method": None,
            "makespan": None,
            "priority_order": [],
            "orders_tried": result.orders_tried,
            "orders_budget": result.orders_budget,
            "conflicts": [conflict.as_dict() for conflict in result.conflicts],
        }

    def _assert_plan_invariants(
        self, mission: Mission, plan: dict[str, Any], closures: Closures = ()
    ) -> None:
        """Fail loudly rather than publish a plan that breaks the documented invariants."""
        if plan["status"] != "solved":
            return
        map_record = self._load_map(mission.map_id)
        by_id = {agent.id: agent for agent in mission.agents}
        order: list[Agent] = []
        paths: list[tuple[tuple[int, int], ...]] = []
        for entry in plan["agents"]:
            agent_id = entry["agent_id"]
            path = tuple(tuple(cell) for cell in entry["path"])
            if not path or path[0] != by_id[agent_id].start or path[-1] != by_id[agent_id].goal:
                raise ConflictError("internal planner error: a path does not join start to goal")
            for index, cell in enumerate(path):
                if not map_record.walkable(cell):
                    raise ConflictError("internal planner error: a path crosses an obstacle")
                if index and abs(path[index - 1][0] - cell[0]) + abs(path[index - 1][1] - cell[1]) > 1:
                    raise ConflictError("internal planner error: a path is not continuous")
                for closure in closures:
                    if closure.start_tick <= index <= closure.end_tick and cell in closure.cells_set:
                        raise ConflictError(
                            "internal planner error: a path occupies a temporarily closed cell"
                        )
            if entry["arrival"] != len(path) - 1:
                raise ConflictError("internal planner error: arrival does not match the path length")
            order.append(by_id[agent_id])
            paths.append(path)
        if len({tuple(path[-1]) for path in paths}) != len(paths):
            raise ConflictError("internal planner error: two agents settle on the same goal cell")
        for timestep in range(plan["makespan"] + 1):
            held = [position_at(path, timestep) for path in paths]
            occupied = [cell for cell in held if cell is not None]
            if len(set(occupied)) != len(occupied):
                raise ConflictError("internal planner error: two agents share a cell at one timestep")
        if max(len(path) - 1 for path in paths) != plan["makespan"]:
            raise ConflictError("internal planner error: makespan is not the latest arrival")
        if detect_conflicts(tuple(order), paths):
            raise ConflictError("internal planner error: the published plan still has a conflict")

    def _idempotent(
        self, key: str | None, operation: str, action: Callable[[], dict[str, Any]]
    ) -> dict[str, Any]:
        if not key:
            raise ValidationError("Idempotency-Key header is required")
        with self.store.transaction() as connection:
            existing = connection.execute(
                "SELECT operation, response FROM idempotency WHERE key = ?", (key,)
            ).fetchone()
            if existing:
                if existing["operation"] != operation:
                    raise ConflictError("idempotency key was already used for another operation")
                return self.store.decode(existing["response"])
            response = action()
            # Store and return the same encoding so a replayed request is
            # byte-identical to the first response.
            encoded = self.store.encode(response)
            connection.execute(
                "INSERT INTO idempotency(key, operation, response) VALUES (?, ?, ?)",
                (key, operation, encoded),
            )
            return self.store.decode(encoded)


__all__ = ["SwarmGrid", "Conflict"]

from __future__ import annotations

import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import urlsplit

from .errors import SwarmGridError, NotFoundError, ValidationError
from .service import SwarmGrid


class Handler(BaseHTTPRequestHandler):
    service: SwarmGrid

    def log_message(self, format: str, *args: Any) -> None:
        return

    def _json(self, status: int, value: Any) -> None:
        body = json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _body(self) -> Any:
        content_type = self.headers.get("Content-Type", "")
        if content_type.split(";", 1)[0].strip().lower() != "application/json":
            raise ValidationError("Content-Type must be application/json")
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length <= 0 or length > 1_000_000:
                raise ValueError
            return json.loads(self.rfile.read(length))
        except (ValueError, json.JSONDecodeError) as error:
            raise ValidationError("request body must be valid JSON") from error

    def _dispatch(self) -> tuple[int, Any]:
        path = urlsplit(self.path).path
        parts = [part for part in path.split("/") if part]
        if self.command == "GET" and parts == ["health"]:
            return 200, {"status": "ok"}
        if self.command == "POST" and parts == ["maps"]:
            return 201, self.service.create_map(self._body(), self.headers.get("Idempotency-Key"))
        if self.command == "GET" and len(parts) == 2 and parts[0] == "maps":
            return 200, self.service.get_map(parts[1])
        if self.command == "POST" and parts == ["missions"]:
            return 201, self.service.create_mission(self._body(), self.headers.get("Idempotency-Key"))
        if len(parts) == 2 and parts[0] == "missions" and self.command == "GET":
            return 200, self.service.get_mission(parts[1])
        if len(parts) == 3 and parts[0] == "missions" and parts[2] == "plan" and self.command == "POST":
            return 200, self.service.plan(
                parts[1], self._body(), self.headers.get("Idempotency-Key")
            )
        if (
            len(parts) == 3
            and parts[0] == "missions"
            and parts[2] == "schedule"
            and self.command == "GET"
        ):
            return 200, self.service.schedule(parts[1])
        raise NotFoundError("route was not found")

    def _handle(self) -> None:
        try:
            status, response = self._dispatch()
            self._json(status, response)
        except SwarmGridError as error:
            self._json(error.status, {"error": {"code": error.code, "message": str(error)}})
        except Exception:
            self._json(500, {"error": {"code": "internal_error", "message": "internal server error"}})

    do_GET = _handle
    do_POST = _handle


def main() -> None:
    parser = argparse.ArgumentParser(description="Run the SwarmGrid MAPF scheduling service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", default=8080, type=int)
    parser.add_argument("--database", default="swarmgrid.db")
    arguments = parser.parse_args()
    Handler.service = SwarmGrid(arguments.database)
    server = ThreadingHTTPServer((arguments.host, arguments.port), Handler)
    print(f"SwarmGrid listening on http://{arguments.host}:{arguments.port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from .errors import ValidationError

MAX_IDENTIFIER = 100
MAX_DIMENSION = 64
MAX_CELLS = 4096
MAX_AGENTS = 32
MAX_CLOSURE_CELLS = 64
MAX_CLOSURES = 64
MAX_TICK = 100_000

Point = tuple[int, int]


def identifier(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or len(value) > MAX_IDENTIFIER:
        raise ValidationError(f"{field} must be a non-empty string of at most {MAX_IDENTIFIER} characters")
    if value != value.strip():
        raise ValidationError(f"{field} must not have leading or trailing whitespace")
    return value


def integer(value: Any, field: str, minimum: int, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValidationError(f"{field} must be an integer")
    if value < minimum or value > maximum:
        raise ValidationError(f"{field} must be between {minimum} and {maximum}")
    return value


def point(value: Any, field: str, width: int, height: int) -> Point:
    if not isinstance(value, list) or len(value) != 2:
        raise ValidationError(f"{field} must be a [x, y] pair")
    x = integer(value[0], f"{field}[0]", 0, width - 1)
    y = integer(value[1], f"{field}[1]", 0, height - 1)
    return (x, y)


def decode_point(value: Any) -> Point:
    return (int(value[0]), int(value[1]))


@dataclass(frozen=True)
class Map:
    """A rectangular 4-connected grid; `obstacle` marks cells agents may never enter."""

    id: str
    width: int
    height: int
    rows: tuple[str, ...]
    obstacle: str

    @classmethod
    def parse(cls, raw: Any) -> "Map":
        if not isinstance(raw, dict):
            raise ValidationError("map must be an object")
        allowed = {"id", "width", "height", "grid", "obstacle"}
        unknown = sorted(set(raw) - allowed)
        if unknown:
            raise ValidationError(f"map contains unknown fields: {', '.join(unknown)}")
        required = {"id", "width", "height", "grid"}
        missing = sorted(required - set(raw))
        if missing:
            raise ValidationError(f"map is missing required fields: {', '.join(missing)}")
        map_id = identifier(raw["id"], "map id")
        width = integer(raw["width"], "width", 1, MAX_DIMENSION)
        height = integer(raw["height"], "height", 1, MAX_DIMENSION)
        if width * height > MAX_CELLS:
            raise ValidationError(f"map may not exceed {MAX_CELLS} cells")
        if "grid" in raw and isinstance(raw["grid"], list) and len(raw["grid"]) != height:
            raise ValidationError(f"grid must be an array of exactly {height} row strings")
        obstacle = raw.get("obstacle", "#")
        if not isinstance(obstacle, str) or len(obstacle) != 1 or obstacle.isspace():
            raise ValidationError("obstacle must be a single non-whitespace character")
        grid = raw["grid"]
        if not isinstance(grid, list) or len(grid) != height:
            raise ValidationError(f"grid must be an array of exactly {height} row strings")
        rows: list[str] = []
        for index, row in enumerate(grid):
            if not isinstance(row, str):
                raise ValidationError(f"grid row {index} must be a string")
            if len(row) != width:
                raise ValidationError(f"grid row {index} must be exactly {width} characters long")
            for column, char in enumerate(row):
                if char not in (".", obstacle):
                    raise ValidationError(
                        f"grid row {index} column {column} must be '.' or the obstacle character {obstacle!r}"
                    )
            rows.append(row)
        return cls(map_id, width, height, tuple(rows), obstacle)

    def walkable(self, cell: Point) -> bool:
        x, y = cell
        if x < 0 or y < 0 or x >= self.width or y >= self.height:
            return False
        return self.rows[y][x] != self.obstacle

    def index(self, cell: Point) -> int:
        return cell[1] * self.width + cell[0]

    def neighbors(self, cell: Point) -> tuple[Point, ...]:
        x, y = cell
        candidates = ((x + 1, y), (x, y + 1), (x - 1, y), (x, y - 1))
        return tuple(candidate for candidate in candidates if self.walkable(candidate))

    def as_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "width": self.width,
            "height": self.height,
            "grid": list(self.rows),
            "obstacle": self.obstacle,
        }


@dataclass(frozen=True)
class Closure:
    """A temporary closure: `cells` may not be occupied during [start_tick, end_tick].

    The interval is closed on both ends. Outside it the cells are ordinary
    walkable cells. Cells must be in the map and may not be static obstacles.
    """

    cells: tuple[Point, ...]
    start_tick: int
    end_tick: int

    @classmethod
    def parse(cls, raw: Any, map_record: Map, field: str) -> "Closure":
        if not isinstance(raw, dict):
            raise ValidationError(f"{field} must be an object")
        allowed = {"cells", "start_tick", "end_tick"}
        unknown = sorted(set(raw) - allowed)
        if unknown:
            raise ValidationError(f"{field} contains unknown fields: {', '.join(unknown)}")
        missing = sorted(allowed - set(raw))
        if missing:
            raise ValidationError(f"{field} is missing required fields: {', '.join(missing)}")
        start_tick = integer(raw["start_tick"], f"{field}.start_tick", 0, MAX_TICK)
        end_tick = integer(raw["end_tick"], f"{field}.end_tick", 0, MAX_TICK)
        if start_tick > end_tick:
            raise ValidationError(f"{field}.start_tick must not be greater than {field}.end_tick")
        raw_cells = raw["cells"]
        if not isinstance(raw_cells, list) or not raw_cells:
            raise ValidationError(f"{field}.cells must be a non-empty array")
        if len(raw_cells) > MAX_CLOSURE_CELLS:
            raise ValidationError(f"{field}.cells may not exceed {MAX_CLOSURE_CELLS} cells")
        cells = tuple(
            point(entry, f"{field}.cells[{index}]", map_record.width, map_record.height)
            for index, entry in enumerate(raw_cells)
        )
        if len(set(cells)) != len(cells):
            raise ValidationError(f"{field}.cells must not repeat a cell")
        for cell in cells:
            if not map_record.walkable(cell):
                raise ValidationError(f"{field}.cells {list(cell)} is an obstacle cell")
        return cls(cells, start_tick, end_tick)

    @property
    def cells_set(self) -> frozenset[Point]:
        return frozenset(self.cells)

    def as_dict(self) -> dict[str, Any]:
        return {
            "cells": [list(cell) for cell in self.cells],
            "start_tick": self.start_tick,
            "end_tick": self.end_tick,
        }


def parse_closures(raw: Any, map_record: Map) -> tuple[Closure, ...]:
    """Validate the optional `closures` array of a plan request body."""
    if raw is None:
        return ()
    if not isinstance(raw, list):
        raise ValidationError("closures must be an array")
    if len(raw) > MAX_CLOSURES:
        raise ValidationError(f"closures may not exceed {MAX_CLOSURES} entries")
    return tuple(
        Closure.parse(entry, map_record, f"closures[{index}]")
        for index, entry in enumerate(raw)
    )


@dataclass(frozen=True)
class Agent:
    id: str
    start: Point
    goal: Point

    @classmethod
    def parse(cls, raw: Any, map_record: Map, field: str) -> "Agent":
        if not isinstance(raw, dict):
            raise ValidationError(f"{field} must be an object")
        unknown = sorted(set(raw) - {"id", "start", "goal"})
        if unknown:
            raise ValidationError(f"{field} contains unknown fields: {', '.join(unknown)}")
        missing = sorted({"id", "start", "goal"} - set(raw))
        if missing:
            raise ValidationError(f"{field} is missing required fields: {', '.join(missing)}")
        agent_id = identifier(raw["id"], f"{field}.id")
        start = point(raw["start"], f"{field}.start", map_record.width, map_record.height)
        goal = point(raw["goal"], f"{field}.goal", map_record.width, map_record.height)
        if not map_record.walkable(start):
            raise ValidationError(f"{field}.start {list(start)} is an obstacle cell")
        if not map_record.walkable(goal):
            raise ValidationError(f"{field}.goal {list(goal)} is an obstacle cell")
        return cls(agent_id, start, goal)

    def as_dict(self) -> dict[str, Any]:
        return {"id": self.id, "start": list(self.start), "goal": list(self.goal)}


@dataclass(frozen=True)
class Mission:
    id: str
    map_id: str
    agents: tuple[Agent, ...]

    @classmethod
    def parse(cls, raw: Any, map_record: Map) -> "Mission":
        if not isinstance(raw, dict):
            raise ValidationError("mission must be an object")
        unknown = sorted(set(raw) - {"id", "map_id", "agents"})
        if unknown:
            raise ValidationError(f"mission contains unknown fields: {', '.join(unknown)}")
        missing = sorted({"id", "map_id", "agents"} - set(raw))
        if missing:
            raise ValidationError(f"mission is missing required fields: {', '.join(missing)}")
        mission_id = identifier(raw["id"], "mission id")
        map_id = identifier(raw["map_id"], "map_id")
        raw_agents = raw["agents"]
        if not isinstance(raw_agents, list) or not raw_agents:
            raise ValidationError("agents must be a non-empty array")
        if len(raw_agents) > MAX_AGENTS:
            raise ValidationError(f"a mission may not exceed {MAX_AGENTS} agents")
        agents = tuple(
            Agent.parse(entry, map_record, f"agents[{index}]") for index, entry in enumerate(raw_agents)
        )
        ids = [agent.id for agent in agents]
        if len(set(ids)) != len(ids):
            raise ValidationError("agent ids must be unique within a mission")
        starts = [agent.start for agent in agents]
        if len(set(starts)) != len(starts):
            raise ValidationError("agent start cells must be unique: two agents may not start on one cell")
        for agent in agents:
            if agent.start == agent.goal:
                raise ValidationError(f"agent {agent.id} already starts on its goal cell")
        return cls(mission_id, map_id, agents)

    def order(self, priority: list[str]) -> tuple[Agent, ...]:
        by_id = {agent.id: agent for agent in self.agents}
        return tuple(by_id[agent_id] for agent_id in priority)

    def as_dict(self) -> dict[str, Any]:
        return {"id": self.id, "map_id": self.map_id, "agents": [agent.as_dict() for agent in self.agents]}

class SwarmGridError(Exception):
    code = "internal_error"
    status = 500


class ValidationError(SwarmGridError):
    code = "validation_error"
    status = 400


class NotFoundError(SwarmGridError):
    code = "not_found"
    status = 404


class ConflictError(SwarmGridError):
    code = "conflict"
    status = 409


class UnsolvableError(SwarmGridError):
    """A mission has no collision-free plan for any priority order that was tried."""

    code = "unsolvable"
    status = 409

from __future__ import annotations

import json
import sqlite3
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterator


class Store:
    """SQLite persistence for maps, missions, and idempotency records."""

    def __init__(self, path: str):
        if path != ":memory:":
            Path(path).parent.mkdir(parents=True, exist_ok=True)
        self.connection = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
        self.connection.row_factory = sqlite3.Row
        self.connection.execute("PRAGMA journal_mode = WAL")
        self.connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS maps (
              id TEXT PRIMARY KEY,
              document TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS missions (
              id TEXT PRIMARY KEY,
              map_id TEXT NOT NULL REFERENCES maps(id),
              state TEXT NOT NULL,
              plan TEXT
            );
            CREATE TABLE IF NOT EXISTS idempotency (
              key TEXT PRIMARY KEY,
              operation TEXT NOT NULL,
              response TEXT NOT NULL
            );
            """
        )

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        self.connection.execute("BEGIN IMMEDIATE")
        try:
            yield self.connection
        except Exception:
            self.connection.execute("ROLLBACK")
            raise
        else:
            self.connection.execute("COMMIT")

    @staticmethod
    def encode(value: Any) -> str:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    @staticmethod
    def decode(value: str) -> Any:
        return json.loads(value)

    @staticmethod
    def now() -> str:
        return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")

import tempfile
import unittest
from pathlib import Path

from swarmgrid.errors import ConflictError, NotFoundError, ValidationError
from swarmgrid.service import SwarmGrid


def corridor_map(map_id: str = "corridor") -> dict:
    """A 5x3 room split by an obstacle wall with a single gap in the middle."""
    return {
        "id": map_id,
        "width": 5,
        "height": 3,
        "grid": [
            ".....",
            "..##.",
            ".....",
        ],
    }


class MapValidationTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.service = SwarmGrid(str(Path(self.directory.name) / "test.db"))

    def tearDown(self):
        self.directory.cleanup()

    def test_create_map_returns_normalized_document(self):
        created = self.service.create_map(corridor_map(), "map-1")
        self.assertEqual(
            {
                "id": "corridor",
                "width": 5,
                "height": 3,
                "grid": [".....", "..##.", "....."],
                "obstacle": "#",
            },
            created,
        )
        self.assertEqual(created, self.service.get_map("corridor"))

    def test_custom_obstacle_character(self):
        created = self.service.create_map(
            {"id": "custom", "width": 3, "height": 1, "grid": ["x.."], "obstacle": "x"}, "k1"
        )
        self.assertEqual("x", created["obstacle"])

    def test_unknown_map_field_is_rejected(self):
        with self.assertRaisesRegex(ValidationError, "unknown fields"):
            self.service.create_map({**corridor_map(), "notes": "hi"}, "k1")

    def test_grid_shape_is_validated(self):
        base = {"id": "m", "width": 3, "height": 2}
        cases = [
            ({**base, "grid": ["..."]}, "exactly 2 row"),
            ({**base, "grid": ["...", ".."]}, "exactly 3 characters"),
            ({**base, "grid": ["...", "..o"], "obstacle": "@"}, "must be '.' or the obstacle"),
            ({**base, "grid": ["...", 5]}, "must be a string"),
        ]
        for index, (payload, pattern) in enumerate(cases):
            with self.subTest(index=index):
                with self.assertRaisesRegex(ValidationError, pattern):
                    self.service.create_map(payload, f"k{index}")

    def test_dimension_bounds_are_validated(self):
        def payload(width, height):
            return {"id": "m", "width": width, "height": height, "grid": ["." * width] * height}

        def rejected(payload, pattern, key):
            with self.assertRaisesRegex(ValidationError, pattern):
                self.service.create_map(payload, key)

        rejected(payload(0, 1), "between 1 and 64", "k1")
        rejected(payload(3, 0), "between 1 and 64", "k2")
        rejected(payload(65, 1), "between 1 and 64", "k3")
        rejected({"id": "m", "width": 3.0, "height": 1, "grid": ["..."]}, "must be an integer", "k4")
        self.assertEqual(64, len(self.service.create_map(payload(64, 64), "k5")["grid"]))

    def test_duplicate_map_is_a_conflict(self):
        self.service.create_map(corridor_map(), "k1")
        with self.assertRaisesRegex(ConflictError, "already exists"):
            self.service.create_map(corridor_map(), "k2")

    def test_missing_map_is_not_found(self):
        with self.assertRaises(NotFoundError):
            self.service.get_map("nope")

    def test_idempotency_key_is_required_and_replayable(self):
        with self.assertRaisesRegex(ValidationError, "Idempotency-Key"):
            self.service.create_map(corridor_map(), None)
        first = self.service.create_map(corridor_map(), "same")
        self.assertEqual(first, self.service.create_map(corridor_map(), "same"))

    def test_idempotency_key_cannot_cross_operations(self):
        self.service.create_map(corridor_map(), "shared")
        with self.assertRaises(ConflictError):
            self.service.create_mission(
                {
                    "id": "m1",
                    "map_id": "corridor",
                    "agents": [{"id": "a", "start": [0, 0], "goal": [4, 0]}],
                },
                "shared",
            )


class MissionValidationTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.service = SwarmGrid(str(Path(self.directory.name) / "test.db"))
        self.service.create_map(corridor_map(), "map-1")

    def tearDown(self):
        self.directory.cleanup()

    def mission(self, agents, mission_id="m1"):
        return {"id": mission_id, "map_id": "corridor", "agents": agents}

    def test_create_mission_starts_in_created_state(self):
        created = self.service.create_mission(
            self.mission([{"id": "a", "start": [0, 0], "goal": [4, 0]}]), "k1"
        )
        self.assertEqual("created", created["status"])
        self.assertIsNone(self.service.get_mission("m1")["plan"])

    def test_unknown_mission_field_is_rejected(self):
        payload = {**self.mission([{"id": "a", "start": [0, 0], "goal": [4, 0]}]), "priority": []}
        with self.assertRaisesRegex(ValidationError, "unknown fields"):
            self.service.create_mission(payload, "k1")

    def test_unknown_agent_field_is_rejected(self):
        with self.assertRaisesRegex(ValidationError, "agents\\[0\\] contains unknown fields"):
            self.service.create_mission(
                self.mission([{"id": "a", "start": [0, 0], "goal": [4, 0], "speed": 2}]), "k1"
            )

    def test_map_must_exist(self):
        with self.assertRaises(NotFoundError):
            self.service.create_mission(
                {"id": "m1", "map_id": "missing", "agents": [{"id": "a", "start": [0, 0], "goal": [4, 0]}]},
                "k1",
            )

    def test_agents_must_be_unique_and_distinguishable(self):
        with self.assertRaisesRegex(ValidationError, "unique"):
            self.service.create_mission(
                self.mission(
                    [
                        {"id": "a", "start": [0, 0], "goal": [4, 0]},
                        {"id": "a", "start": [0, 2], "goal": [4, 2]},
                    ]
                ),
                "k1",
            )
        with self.assertRaisesRegex(ValidationError, "start cells must be unique"):
            self.service.create_mission(
                self.mission(
                    [
                        {"id": "a", "start": [0, 0], "goal": [4, 0]},
                        {"id": "b", "start": [0, 0], "goal": [4, 2]},
                    ]
                ),
                "k2",
            )
        with self.assertRaisesRegex(ValidationError, "already starts on its goal"):
            self.service.create_mission(
                self.mission([{"id": "a", "start": [0, 0], "goal": [0, 0]}]), "k3"
            )

    def test_cells_must_be_in_bounds_and_free(self):
        with self.assertRaisesRegex(ValidationError, "between 0 and 4"):
            self.service.create_mission(
                self.mission([{"id": "a", "start": [5, 0], "goal": [4, 0]}]), "k1"
            )
        with self.assertRaisesRegex(ValidationError, "obstacle"):
            self.service.create_mission(
                self.mission([{"id": "a", "start": [0, 0], "goal": [2, 1]}]), "k2"
            )
        with self.assertRaisesRegex(ValidationError, r"\[x, y\] pair"):
            self.service.create_mission(
                self.mission([{"id": "a", "start": [0], "goal": [4, 0]}]), "k3"
            )

    def test_duplicate_mission_is_a_conflict(self):
        payload = self.mission([{"id": "a", "start": [0, 0], "goal": [4, 0]}])
        self.service.create_mission(payload, "k1")
        with self.assertRaisesRegex(ConflictError, "already exists"):
            self.service.create_mission(payload, "k2")


class PlanningTests(unittest.TestCase):
    def setUp(self):
        self.directory = tempfile.TemporaryDirectory()
        self.service = SwarmGrid(str(Path(self.directory.name) / "test.db"))
        self.service.create_map(corridor_map(), "map-1")

    def tearDown(self):
        self.directory.cleanup()

    def create(self, agents, mission_id="m1"):
        self.service.create_mission(
            {"id": mission_id, "map_id": "corridor", "agents": agents}, f"mission-{mission_id}"
        )

    def test_single_agent_takes_the_shortest_route(self):
        self.create([{"id": "a", "start": [0, 0], "goal": [4, 0]}])
        plan = self.service.plan("m1", {}, "p1")
        self.assertEqual("solved", plan["status"])
        self.assertEqual(4, plan["makespan"])
        self.assertEqual(["a"], plan["priority_order"])
        self.assertEqual(
            [[0, 0], [1, 0], [2, 0], [3, 0], [4, 0]], plan["agents"][0]["path"]
        )
        self.assertEqual(4, plan["agents"][0]["arrival"])

    def test_crossing_agents_are_resolved_by_replanning(self):
        self.create(
            [
                {"id": "a", "start": [0, 0], "goal": [4, 0]},
                {"id": "b", "start": [4, 0], "goal": [0, 0]},
            ]
        )
        plan = self.service.plan("m1", {}, "p1")
        self.assertEqual("solved", plan["status"])
        self.assertEqual("priority", plan["method"])
        self.assertEqual(["a", "b"], plan["priority_order"])
        self.assertEqual(1, plan["orders_tried"])
        # a takes the direct lane, so b yields and detours through the lower
        # lane instead of swapping with a.
        self.assertEqual(4, plan["agents"][0]["arrival"])
        self.assertEqual(8, plan["agents"][1]["arrival"])
        self.assertEqual(
            [[4, 0], [4, 1], [4, 2], [3, 2], [2, 2], [1, 2], [0, 2], [0, 1], [0, 0]],
            plan["agents"][1]["path"],
        )

    def test_plan_invariants_hold_for_every_published_plan(self):
        open_map = {
            "id": "open",
            "width": 6,
            "height": 4,
            "grid": ["......", "......", "......", "......"],
        }
        self.service.create_map(open_map, "map-open")
        self.service.create_mission(
            {
                "id": "fleet",
                "map_id": "open",
                "agents": [
                    {"id": "a", "start": [0, 0], "goal": [5, 0]},
                    {"id": "b", "start": [5, 3], "goal": [0, 3]},
                    {"id": "c", "start": [2, 1], "goal": [2, 2]},
                ],
            },
            "mission-fleet",
        )
        plan = self.service.plan("fleet", {}, "p1")
        self.assertEqual("solved", plan["status"])
        map_record = self.service.get_map("open")
        trajectories: dict[str, list[tuple]] = {}
        for entry in plan["agents"]:
            path = [tuple(cell) for cell in entry["path"]]
            self.assertEqual(tuple(entry["start"]), path[0])
            self.assertEqual(tuple(entry["goal"]), path[-1])
            self.assertEqual(len(path) - 1, entry["arrival"])
            for index, cell in enumerate(path):
                self.assertNotEqual("#", map_record["grid"][cell[1]][cell[0]])
                if index:
                    previous = path[index - 1]
                    self.assertLessEqual(
                        abs(previous[0] - cell[0]) + abs(previous[1] - cell[1]), 1
                    )
            trajectories[entry["agent_id"]] = path
        for timestep in range(plan["makespan"] + 1):
            occupied = [
                path[timestep]
                for path in trajectories.values()
                if timestep < len(path)
            ]
            self.assertEqual(len(occupied), len(set(occupied)), f"collision at t={timestep}")
        self.assertEqual(plan["makespan"], max(entry["arrival"] for entry in plan["agents"]))
        self.assertEqual(3, len({tuple(path[-1]) for path in trajectories.values()}))

    def test_priority_order_can_be_pinned_explicitly(self):
        square = {"id": "square", "width": 2, "height": 2, "grid": ["..", ".."]}
        self.service.create_map(square, "map-square")
        self.service.create_mission(
            {
                "id": "corner",
                "map_id": "square",
                "agents": [
                    {"id": "agv-1", "start": [0, 0], "goal": [1, 1]},
                    {"id": "agv-2", "start": [1, 0], "goal": [0, 0]},
                ],
            },
            "mission-corner",
        )
        pinned = self.service.plan("corner", {"priority": ["agv-2", "agv-1"]}, "p-pinned")
        self.assertEqual("solved", pinned["status"])
        self.assertEqual(["agv-2", "agv-1"], pinned["priority_order"])
        self.assertEqual(1, pinned["orders_budget"])
        paths = {entry["agent_id"]: entry["path"] for entry in pinned["agents"]}
        self.assertEqual([[1, 0], [0, 0]], paths["agv-2"])
        self.assertEqual(
            [[0, 0], [0, 1], [1, 1]], paths["agv-1"]
        )
        self.assertEqual(2, pinned["makespan"])
        self.assertEqual(pinned["makespan"], max(entry["arrival"] for entry in pinned["agents"]))
        for frame in self.service.schedule("corner")["timeline"]:
            live = [tuple(value) for value in frame["positions"].values() if value is not None]
            self.assertEqual(len(live), len(set(live)))

    def test_head_on_agents_in_a_single_lane_are_unsolvable(self):
        narrow = {
            "id": "narrow",
            "width": 4,
            "height": 1,
            "grid": ["...."],
        }
        self.service.create_map(narrow, "map-narrow")
        self.service.create_mission(
            {
                "id": "swap",
                "map_id": "narrow",
                "agents": [
                    {"id": "a", "start": [0, 0], "goal": [3, 0]},
                    {"id": "b", "start": [3, 0], "goal": [0, 0]},
                ],
            },
            "mission-swap",
        )
        plan = self.service.plan("swap", {}, "p1")
        self.assertEqual("unsolvable", plan["status"])
        self.assertIsNone(plan["makespan"])
        self.assertEqual([], plan["priority_order"])
        self.assertTrue(plan["conflicts"])
        kinds = {conflict["type"] for conflict in plan["conflicts"]}
        self.assertTrue(kinds <= {"vertex", "edge", "unreachable_goal"})
        self.assertEqual(2, plan["orders_tried"])
        self.assertEqual(2, plan["orders_budget"])
        state = self.service.get_mission("swap")
        self.assertEqual("unsolvable", state["status"])
        self.assertIsNone(state["plan"])

    def test_unreachable_goal_is_reported_without_planning(self):
        walled = {"id": "walled", "width": 5, "height": 1, "grid": ["..#.."]}
        self.service.create_map(walled, "map-walled")
        self.service.create_mission(
            {
                "id": "sealed",
                "map_id": "walled",
                "agents": [{"id": "a", "start": [0, 0], "goal": [4, 0]}],
            },
            "mission-walled",
        )
        plan = self.service.plan("sealed", {}, "p1")
        self.assertEqual("unsolvable", plan["status"])
        self.assertEqual(0, plan["orders_tried"])
        self.assertEqual(["unreachable_goal"], [conflict["type"] for conflict in plan["conflicts"]])
        self.assertEqual([[4, 0]], [plan["conflicts"][0]["position"]])

    def test_unreachable_start_is_unsolvable(self):
        # (0, 0) and (0, 1) sit in a sealed pocket; the goal is outside it.
        sealer = {"id": "sealer", "width": 5, "height": 3, "grid": [".#...", "##...", "....."]}
        self.service.create_map(sealer, "map-sealer")
        self.service.create_mission(
            {
                "id": "sealed",
                "map_id": "sealer",
                "agents": [{"id": "a", "start": [0, 0], "goal": [0, 2]}],
            },
            "mission-sealed",
        )
        plan = self.service.plan("sealed", {}, "p1")
        self.assertEqual("unsolvable", plan["status"])
        self.assertEqual("unreachable_goal", plan["conflicts"][0]["type"])
        self.assertEqual("a", plan["conflicts"][0]["agent"])
        self.assertEqual([[0, 2]], [plan["conflicts"][0]["position"]])

    def test_explicit_priority_order_is_honoured(self):
        self.create(
            [
                {"id": "a", "start": [0, 0], "goal": [4, 0]},
                {"id": "b", "start": [4, 0], "goal": [0, 0]},
            ]
        )
        plan = self.service.plan("m1", {"priority": ["b", "a"]}, "p1")
        self.assertEqual("solved", plan["status"])
        self.assertEqual(["b", "a"], plan["priority_order"])
        self.assertEqual(1, plan["orders_budget"])

    def test_priority_must_cover_the_mission_agents(self):
        self.create(
            [
                {"id": "a", "start": [0, 0], "goal": [4, 0]},
                {"id": "b", "start": [4, 0], "goal": [0, 0]},
            ]
        )
        for priority, pattern in (
            (["a"], "exactly once"),
            (["a", "a"], "must not repeat"),
            (["a", "z"], "exactly once"),
            (["a", 7], "non-empty agent id strings"),
        ):
            with self.subTest(priority=priority):
                with self.assertRaisesRegex(ValidationError, pattern):
                    self.service.plan("m1", {"priority": priority}, "px")

    def test_plan_options_are_validated(self):
        self.create([{"id": "a", "start": [0, 0], "goal": [4, 0]}])
        with self.assertRaisesRegex(ValidationError, "unknown fields"):
            self.service.plan("m1", {"order": ["a"]}, "p1")
        with self.assertRaisesRegex(ValidationError, "order_budget"):
            self.service.plan("m1", {"order_budget": 0}, "p2")
        with self.assertRaisesRegex(ValidationError, "order_budget"):
            self.service.plan("m1", {"order_budget": True}, "p3")
        with self.assertRaisesRegex(ValidationError, "Idempotency-Key"):
            self.service.plan("m1", {}, None)

    def test_planning_missing_mission_is_not_found(self):
        with self.assertRaises(NotFoundError):
            self.service.plan("ghost", {}, "p1")

    def test_repeated_planning_returns_the_recorded_plan(self):
        self.create([{"id": "a", "start": [0, 0], "goal": [4, 0]}])
        first = self.service.plan("m1", {}, "k-plan")
        repeated = self.service.plan("m1", {}, "k-plan")
        again = self.service.plan("m1", {"priority": ["a"]}, "k-plan-2")
        self.assertEqual(first, repeated)
        self.assertEqual(first, again)

    def test_schedule_exposes_one_frame_per_timestep(self):
        self.create(
            [
                {"id": "a", "start": [0, 0], "goal": [1, 0]},
                {"id": "b", "start": [4, 0], "goal": [0, 0]},
            ]
        )
        plan = self.service.plan("m1", {}, "p1")
        schedule = self.service.schedule("m1")
        self.assertEqual(plan["makespan"], schedule["makespan"])
        self.assertEqual(plan["makespan"] + 1, len(schedule["timeline"]))
        self.assertEqual([0, 1], [frame["timestep"] for frame in schedule["timeline"][:2]])
        for frame in schedule["timeline"]:
            self.assertEqual({"a", "b"}, set(frame["positions"]))
        self.assertEqual({"a": [0, 0], "b": [4, 0]}, schedule["timeline"][0]["positions"])
        # a finishes on its goal after one tick, so later frames report null for it.
        self.assertEqual({"a": None, "b": [0, 0]}, schedule["timeline"][-1]["positions"])
        for frame in schedule["timeline"]:
            live = [tuple(value) for value in frame["positions"].values() if value is not None]
            self.assertEqual(len(live), len(set(live)))

    def test_schedule_requires_a_solved_plan(self):
        self.create([{"id": "a", "start": [0, 0], "goal": [4, 0]}])
        with self.assertRaisesRegex(ConflictError, "no solved plan"):
            self.service.schedule("m1")

    def test_schedule_of_an_unsolvable_mission_conflicts(self):
        narrow = {"id": "narrow", "width": 4, "height": 1, "grid": ["...."]}
        self.service.create_map(narrow, "map-narrow")
        self.service.create_mission(
            {
                "id": "swap",
                "map_id": "narrow",
                "agents": [
                    {"id": "a", "start": [0, 0], "goal": [3, 0]},
                    {"id": "b", "start": [3, 0], "goal": [0, 0]},
                ],
            },
            "mission-swap",
        )
        self.service.plan("swap", {}, "p1")
        with self.assertRaisesRegex(ConflictError, "no solved plan"):
            self.service.schedule("swap")

    def test_plans_survive_a_service_restart(self):
        path = str(Path(self.directory.name) / "restart.db")
        first = SwarmGrid(path)
        first.create_map(corridor_map(), "map-1")
        first.create_mission(
            {
